<script setup>
import {ref,computed} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import issues from '../data/issues.json' with {type:'json'};
import articles from '../data/articles.json' with {type:'json'};
import {assetUrl} from '../api/assetUrl.js';
const route=useRoute(),router=useRouter(),year=ref('all');
const years=[...new Set(issues.map(i=>i.year))];
const visible=computed(()=>issues.filter(i=>year.value==='all'||String(i.year)===year.value));
const selected=computed(()=>issues.find(i=>String(i.id)===String(route.params.id||route.query.issue||issues[0]?.id)));
const papers=computed(()=>selected.value?articles.filter(a=>a.issueId===selected.value.id||selected.value.articleIds.includes(a.id)):[]);
function select(id){router.push({path:'/all-issues',query:{issue:String(id)}});}
</script>
<template><main id="main" class="page-shell"><section class="all-issues-panel all-issues-page-panel" id="all-issues"><div class="section-heading"><div><p class="eyebrow">Journal archive</p><h1>All Issues</h1><p>Browse published issues and their articles.</p></div></div><div class="issue-archive-layout"><article v-if="selected" class="issue-preview-panel"><div class="issue-preview-cover"><img :src="assetUrl(selected.cover)" :alt="selected.title+' cover'" width="360" height="480"/></div><h2>{{selected.title}}</h2><p>{{selected.date}}</p><p class="section-lede">Selected articles in this catalogue.</p><div class="signature-paper-list"><article v-for="paper in papers" :key="paper.id" class="signature-paper"><span class="signature-kind">{{paper.category}}</span><h3><RouterLink :to="'/articles/'+paper.id">{{paper.title}}</RouterLink></h3><p>{{paper.authors.join(', ')}}</p></article><p v-if="!papers.length" class="empty-state">No articles are available for this issue in the catalogue.</p></div></article><article v-else class="notice-panel"><h2>Issue not found</h2><p>Select an available issue.</p></article><section class="issue-browser-panel" aria-label="Issue archive selector"><div class="issue-year-filter" aria-label="Filter issues by year"><button type="button" class="issue-year-button" :class="{'is-active':year==='all'}" :aria-pressed="year==='all'" @click="year='all'">All</button><button v-for="entry in years" :key="entry" type="button" class="issue-year-button" :class="{'is-active':year===String(entry)}" :aria-pressed="year===String(entry)" @click="year=String(entry)">{{entry}}</button></div><div class="all-issues-grid"><article v-for="entry in visible" :key="entry.id" class="past-issue-card issue-select-card" :class="{'is-active':selected?.id===entry.id}"><button type="button" class="issue-select-button" :aria-pressed="selected?.id===entry.id" @click="select(entry.id)"><img :src="assetUrl(entry.cover)" :alt="entry.title+' cover'" loading="lazy"/><span><span class="type-label">{{entry.year}}</span><strong>{{entry.title}}</strong><small>{{entry.date}}</small></span></button></article></div></section></div></section></main></template>
